using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class ValidateWreckSources
{
 public static object Run(){int checks=0;Action<bool,string> check=(ok,s)=>{checks++;if(!ok)throw new Exception(s);};var rows=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(System.IO.Path.Combine((System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures.")), "GunmaggedonRuntime/build/wreckage/setup.json")))["units"];
 foreach(var row in rows){string path=(string)row["source"];var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);var backup=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/BlueprinterSetupBackups/Wreckage/"+Path.GetFileName(path));check(source&&backup,"Source and backup exist");var old=backup.GetComponentsInChildren<Transform>(true).ToDictionary(t=>AnimationUtility.CalculateTransformPath(t,backup.transform));foreach(var t in source.GetComponentsInChildren<Transform>(true)){string key=AnimationUtility.CalculateTransformPath(t,source.transform);Transform b;check(old.TryGetValue(key,out b)&&t.localPosition==b.localPosition&&t.localRotation==b.localRotation&&t.localScale==b.localScale&&t.gameObject.activeSelf==b.gameObject.activeSelf,"Intact pose/visibility unchanged: "+key);check(t.GetComponents<Component>().Select(c=>c.GetType()).SequenceEqual(b.GetComponents<Component>().Select(c=>c.GetType())),"Intact components unchanged");var r=t.GetComponent<MeshRenderer>();if(r)check(r.sharedMaterials.SequenceEqual(b.GetComponent<MeshRenderer>().sharedMaterials),"Intact textures/materials unchanged");var gun=t.GetComponent<Gun>();if(gun){var prior=b.GetComponent<Gun>();var s=new SerializedObject(gun);var p=new SerializedObject(prior);check(gun.info==prior.info&&gun.Safety==prior.Safety&&s.FindProperty("ammo").intValue==p.FindProperty("ammo").intValue&&s.FindProperty("fireRate").floatValue==p.FindProperty("fireRate").floatValue&&s.FindProperty("reloadTime").floatValue==p.FindProperty("reloadTime").floatValue,"Firing/ammo/reload settings unchanged");}}
 }foreach(var guid in AssetDatabase.FindAssets("t:Material",new[]{"Assets/Blueprinter/Mods/Gunmageddon/Wreckage/Materials"})){var m=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));string token=Path.GetFileNameWithoutExtension(AssetDatabase.GetAssetPath(m)).Split('_').Last();var stem=Path.GetFileNameWithoutExtension(AssetDatabase.GetAssetPath(m));string originalName=stem.Substring(6,stem.Length-6-33);var source=AssetDatabase.LoadAllAssetsAtPath(AssetDatabase.GUIDToAssetPath(token)).OfType<Material>().SingleOrDefault(material=>material.name==originalName);check(source,"Original material identified");check(source.GetTexture("_BaseMap")==m.GetTexture("_BaseMap")&&source.GetTexture("_BumpMap")==m.GetTexture("_BumpMap")&&source.GetTextureScale("_BaseMap")==m.GetTextureScale("_BaseMap"),"Original paint/normal assets and mapping reused");}
 var report=new{passed=true,checks,units=rows.Count(),note="Intact poses/components/materials and gun settings compared with pre-migration backups; original texture references preserved"};var json=Newtonsoft.Json.JsonConvert.SerializeObject(report);File.WriteAllText(System.IO.Path.Combine((System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures.")), "GunmaggedonRuntime/build/wreckage/source-validation.json"),json);return json;}
}
